#include <stdio.h>
/*
 * ex01：内核态 / 用户态 状态机
 * 为什么：教材说「用户态不能执行特权指令」，但这句话到底怎么落地？
 *        落地方式就是 CPU 里有一个「模式位」，每条指令执行前先看模式位。
 * 本程序把一条指令序列喂给状态机，打印执行前后的模式与判定理由。
 */
typedef struct {
    const char *name;   /* 指令助记符 */
    int privileged;     /* 1 = 特权指令，只有内核态能执行 */
    int enters_kernel;  /* 1 = 陷入指令，用户态可主动执行，效果是进内核 */
    int exits_kernel;   /* 1 = 返回指令，把模式位切回用户态 */
} Insn;

int main(void) {
    Insn seq[] = {
        {"mov  eax, 1",     0, 0, 0},   /* 普通传送：用户态即可 */
        {"cli (关中断)",    1, 0, 0},   /* 用户态直接执行特权指令 -> 越权 #GP */
        {"iret (异常返回)", 1, 0, 1},   /* 内核处理完异常，把模式位切回用户态 */
        {"syscall (write)", 0, 1, 0},   /* 陷入指令：用户态可以主动执行 */
        {"mov  cr3, eax",   1, 0, 0},   /* 此时已在核心态，特权指令合法 */
        {"iret (中断返回)", 1, 0, 1},   /* 回到用户态 */
        {"add  eax, ebx",   0, 0, 0}
    };
    int n = (int)(sizeof(seq) / sizeof(seq[0]));
    int mode = 0;              /* 0=用户态 1=内核态 */
    int switches = 0;          /* 特权级切换次数 */
    int violations = 0;        /* 越权次数 */

    printf("%-16s %-8s %-8s %s\n", "指令", "执行前", "执行后", "判定");
    printf("--------------------------------------------------------------\n");
    for (int i = 0; i < n; i++) {
        const char *before = mode ? "内核态" : "用户态";
        const char *note;
        if (seq[i].privileged && mode == 0) {
            /* 用户态执行特权指令：硬件产生 #GP 通用保护异常，控制权强制转到内核 */
            note = "越权 -> #GP 异常，强制进内核处理";
            violations++;
            mode = 1;
            switches++;
        } else if (seq[i].enters_kernel && mode == 0) {
            note = "陷入指令：合法切入内核";
            mode = 1;
            switches++;
        } else if (seq[i].exits_kernel && mode == 1) {
            note = "返回到用户态";
            mode = 0;
            switches++;
        } else if (seq[i].privileged) {
            note = "内核态执行特权指令：合法";
        } else {
            note = "普通指令";
        }
        printf("%-16s %-8s %-8s %s\n", seq[i].name, before,
               mode ? "内核态" : "用户态", note);
    }
    printf("\n特权级切换次数=%d  越权次数=%d\n", switches, violations);
    printf("结论：切换只能由「陷入指令 / 中断 / 异常」三种事件触发，普通指令永远改不了模式位。\n");
    return 0;
}
